{
  "versions": [
    {
      "label": "1",
      "angle": "从旅行携带与居家外观切入，先讲轻便收纳和颜色版型，再回到足弓支撑、厚底软弹与静音防滑，最后讲材质打理和价格尺码。",
      "blocks": [
        {
          "stage": "welcome",
          "focus": "开场与互动",
          "sentences": [
            {
              "display_text": "欢迎来到直播间，今天这双鞋，咱们从它怎么陪你出门说起。",
              "spoken_text": "欢迎来到直播间，今天这双鞋，咱们从它怎么陪你出门说起。",
              "kind": "engagement",
              "fact_ids": []
            },
            {
              "display_text": "姐妹平时出门旅行，会不会纠结要不要带自己的拖鞋？",
              "spoken_text": "姐妹平时出门旅行，会不会纠结要不要带自己的拖鞋？",
              "kind": "engagement",
              "fact_ids": []
            }
          ]
        },
        {
          "stage": "pain",
          "focus": "旅行携带与居家外观选择困扰",
          "sentences": [
            {
              "display_text": "住酒店时想换上自己的拖鞋，又怕鞋子硬邦邦、占地方。",
              "spoken_text": "住酒店时想换上自己的拖鞋，又怕鞋子硬邦邦、占地方。",
              "kind": "engagement",
              "fact_ids": []
            },
            {
              "display_text": "在家穿嘛，也想挑一双看着顺眼、颜色不沉闷的。",
              "spoken_text": "在家穿嘛，也想挑一双看着顺眼、颜色不沉闷的。",
              "kind": "engagement",
              "fact_ids": []
            }
          ]
        },
        {
          "stage": "identity",
          "focus": "商品身份",
          "sentences": [
            {
              "display_text": "今天讲的是这双足弓支撑静音防滑厚底凉拖鞋，小蛮腰女款。",
              "spoken_text": "今天讲的是这双足弓支撑静音防滑厚底凉拖鞋，小蛮腰女款。",
              "kind": "product_claim",
              "fact_ids": ["NAME"]
            }
          ]
        },
        {
          "stage": "benefit",
          "focus": "轻便与旅行携带",
          "sentences": [
            {
              "display_text": "它整双鞋走的是轻便路线，出门塞进行李箱不怎么添分量。",
              "spoken_text": "它整双鞋走的是轻便路线，出门塞进行李箱不怎么添分量。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "到了海边想踩沙，换上它就走，不用另带一双厚重的鞋。",
              "spoken_text": "到了海边想踩沙，换上它就走，不用另带一双厚重的鞋。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "日常去楼下倒垃圾、散个步，一脚蹬上就能出门。",
              "spoken_text": "日常去楼下倒垃圾、散个步，一脚蹬上就能出门。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            }
          ]
        },
        {
          "stage": "benefit",
          "focus": "颜色与版型",
          "sentences": [
            {
              "display_text": "颜色选择挺丰富，比如粉色、绿色、蓝色，还有黑色和白色。",
              "spoken_text": "颜色选择挺丰富，比如粉色、绿色、蓝色，还有黑色和白色。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "喜欢亮一点的可以看看橙色、红色，想低调些就选卡其或葡萄紫、烟熏紫。",
              "spoken_text": "喜欢亮一点的可以看看橙色、红色，想低调些就选卡其或葡萄紫、烟熏紫。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "一共十个颜色，每天按心情换着穿，居家也多点小乐趣。",
              "spoken_text": "一共十个颜色，每天按心情换着穿，居家也多点小乐趣。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "版型是厚底平底、一般版型，视觉上能修饰脚型。",
              "spoken_text": "版型是厚底平底、一般版型，视觉上能修饰脚型。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            }
          ]
        },
        {
          "stage": "benefit",
          "focus": "足弓支撑与厚底软弹",
          "sentences": [
            {
              "display_text": "再看脚底这一块，它做了足弓支撑，不是完全平塌塌的鞋底。",
              "spoken_text": "再看脚底这一块，它做了足弓支撑，不是完全平塌塌的鞋底。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "你站着择菜、熨衣服的时候，脚心有个地方托着，久站的压力能缓一缓。",
              "spoken_text": "你站着择菜、熨衣服的时候，脚心有个地方托着，久站的压力能缓一缓。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "加上小蛮腰厚底，踩上去是软弹缓震的感觉，走路多了脚底没那么累。",
              "spoken_text": "加上小蛮腰厚底，踩上去是软弹缓震的感觉，走路多了脚底没那么累。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            }
          ]
        },
        {
          "stage": "benefit",
          "focus": "静音与防滑",
          "sentences": [
            {
              "display_text": "鞋底有静音特性，晚上在室内走动，声音会轻一些。",
              "spoken_text": "鞋底有静音特性，晚上在室内走动，声音会轻一些。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "它也具备防滑特性，在浴室或室内走动时，能多一分踏实感。",
              "spoken_text": "它也具备防滑特性，在浴室或室内走动时，能多一分踏实感。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "浴室地面有水的时候，咱们自己还是要留意，走稳一点。",
              "spoken_text": "浴室地面有水的时候，咱们自己还是要留意，走稳一点。",
              "kind": "engagement",
              "fact_ids": []
            }
          ]
        },
        {
          "stage": "benefit",
          "focus": "材质与打理",
          "sentences": [
            {
              "display_text": "整双鞋是优选 E V A 环保材质一体成型的，没有多余的拼接。",
              "spoken_text": "整双鞋是优选 E V A 环保材质一体成型的，没有多余的拼接。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "材质防臭快干，洗澡沾了水，冲一冲就干净，晾着也干得快。",
              "spoken_text": "材质防臭快干，洗澡沾了水，冲一冲就干净，晾着也干得快。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "不用专门拿刷子抠鞋面，日常打理省事很多。",
              "spoken_text": "不用专门拿刷子抠鞋面，日常打理省事很多。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            }
          ]
        },
        {
          "stage": "specification",
          "focus": "尺码与选择提醒",
          "sentences": [
            {
              "display_text": "尺码从三十六码到四十五码，分成五个区间。",
              "spoken_text": "尺码从三十六码到四十五码，分成五个区间。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "它是标准码，脚背较宽或者脚型偏肉的朋友，建议斟酌大一号。",
              "spoken_text": "它是标准码，脚背较宽或者脚型偏肉的朋友，建议斟酌大一号。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "具体选哪个尺码，可以结合自己平时穿鞋的习惯来定。",
              "spoken_text": "具体选哪个尺码，可以结合自己平时穿鞋的习惯来定。",
              "kind": "engagement",
              "fact_ids": []
            }
          ]
        },
        {
          "stage": "price",
          "focus": "价格与优惠",
          "sentences": [
            {
              "display_text": "这双鞋原价一百七十八新台币，现在限时下杀一百零七新台币。",
              "spoken_text": "这双鞋原价一百七十八新台币，现在限时下杀一百零七新台币。",
              "kind": "product_claim",
              "fact_ids": ["PRICE", "PROMOTION"]
            },
            {
              "display_text": "优惠是限时的，喜欢的朋友可以抓紧看看。",
              "spoken_text": "优惠是限时的，喜欢的朋友可以抓紧看看。",
              "kind": "product_claim",
              "fact_ids": ["PROMOTION"]
            }
          ]
        },
        {
          "stage": "cta",
          "focus": "自然收尾与购买引导",
          "sentences": [
            {
              "display_text": "挑的时候，最值得关注的是足弓支撑、厚底软弹和轻便防臭快干这几点。",
              "spoken_text": "挑的时候，最值得关注的是足弓支撑、厚底软弹和轻便防臭快干这几点。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "颜色和尺码按自己平时的喜好来选，合适再下单。",
              "spoken_text": "颜色和尺码按自己平时的喜好来选，合适再下单。",
              "kind": "engagement",
              "fact_ids": []
            }
          ]
        }
      ]
    }
  ],
  "missing_information": [
    "商品是否包邮、退换货政策、发货时效等履约条件未提供",
    "各颜色和各尺码的具体库存情况未提供",
